1	import type { DocumentPickerResponse } from "@react-native-documents/picker";
2	import {
3	  type AudioMessageContent,
4	  EditedContent,
5	  type EventTimelineItem,
6	  type FileMessageContent,
7	  type ImageMessageContent,
8	  type Mentions,
9	  messageEventContentFromHtml,
10	  messageEventContentFromMarkdown,
11	  MessageType_Tags,
12	  MsgLikeKind_Tags,
13	  TimelineItemContent_Tags,
14	  type UploadParameters,
15	  UploadSource,
16	  type VideoMessageContent,
17	} from "@unomed/react-native-matrix-sdk";
18	import type { Asset } from "react-native-image-picker";
19	import { Blurhash } from "react-native-blurhash";
20	import { createThumbnail } from "react-native-create-thumbnail";
21	import RNFS from "react-native-fs";
22	import { MatrixCore } from "../../matrix-client/services/MatrixCore";
23	import { getEventId } from "../../matrix-client/utils";
24	
25	export class TimelineService {
26	  public static sendMessage = async (
27	    roomId: string,
28	    message: string,
29	    mentions?: Mentions,
30	    htmlBody?: string,
31	  ) => {
32	    const room = MatrixCore.getRoom(roomId);
33	    const timeline = await room.timeline();
34	    if (!timeline) throw new Error("Timeline not found");
35	    let messageContent = htmlBody
36	      ? messageEventContentFromHtml(message, htmlBody)
37	      : messageEventContentFromMarkdown(message);
38	    if (mentions) messageContent = messageContent.withMentions(mentions);
39	    await timeline.send(messageContent);
40	  };
41	
42	  public static replyToMessage = async (
43	    roomId: string,
44	    message: string,
45	    eventId: string,
46	    mentions?: Mentions,
47	    htmlBody?: string,
48	  ) => {
49	    const room = MatrixCore.getRoom(roomId);
50	    const timeline = await room.timeline();
51	    if (!timeline) throw new Error("Timeline not found");
52	    let messageContent = htmlBody
53	      ? messageEventContentFromHtml(message, htmlBody)
54	      : messageEventContentFromMarkdown(message);
55	    if (mentions) messageContent = messageContent.withMentions(mentions);
56	    await timeline.sendReply(messageContent, eventId);
57	  };
58	
59	  public static editMessage = async (
60	    roomId: string,
61	    event: EventTimelineItem,
62	    message: string,
63	    mentions?: Mentions,
64	    htmlBody?: string,
65	  ) => {
66	    const room = MatrixCore.getRoom(roomId);
67	    const timeline = await room.timeline();
68	    if (!timeline) throw new Error("Timeline not found");
69	
70	    if (!event.eventOrTransactionId) {
71	      throw new Error("Event is missing event or transaction id");
72	    }
73	
74	    let messageContent = htmlBody
75	      ? messageEventContentFromHtml(message, htmlBody)
76	      : messageEventContentFromMarkdown(message);
77	    if (mentions) messageContent = messageContent.withMentions(mentions);
78	
79	    const editedContent = EditedContent.RoomMessage.new({
80	      content: messageContent,
81	    });
82	    await timeline.edit(event.eventOrTransactionId, editedContent);
83	  };
84	
85	  public static reportMessage = async (
86	    roomId: string,
87	    event: EventTimelineItem,
88	    reason: string,
89	  ) => {
90	    const room = MatrixCore.getRoom(roomId);
91	    const eventId = getEventId(event);
92	    if (!eventId) throw new Error("Event is missing event id");
93	    await room.reportContent(eventId, undefined, reason);
94	  };
95	
96	  public static deleteMessage = async (
97	    roomId: string,
98	    event: EventTimelineItem,
99	  ) => {
100	    const room = MatrixCore.getRoom(roomId);
101	    const eventId = getEventId(event);
102	    if (!eventId) throw new Error("Event is missing event id");
103	    await room.redact(eventId, undefined);
104	  };
105	
106	  public static forwardMessage = async (
107	    roomId: string,
108	    event: EventTimelineItem,
109	    messageType: ForwardMessageType,
110	  ) => {
111	    const client = MatrixCore.getClient();
112	    const room = MatrixCore.getRoom(roomId);
113	    const timeline = await room.timeline();
114	    if (!timeline) throw new Error("Timeline not found");
115	
116	    if (messageType === "text") {
117	      const textContent = this.getTextContent(event);
118	      if (!textContent) throw new Error("Text content not found");
119	      await timeline.send(messageEventContentFromMarkdown(textContent));
120	      return;
121	    }
122	
123	    if (messageType === "image") {
124	      const imageContent = this.getImageContent(event);
125	      if (!imageContent) throw new Error("Image content not found");
126	
127	      const mediaFile = await client.getMediaFile(
128	        imageContent.source,
129	        imageContent.filename,
130	        imageContent.info?.mimetype || "image/jpeg",
131	        true,
132	        undefined,
133	      );
134	      const filePath = mediaFile.path();
135	      const fileSource: UploadParameters = {
136	        source: new UploadSource.File({ filename: filePath }),
137	        caption: imageContent.caption || undefined,
138	        formattedCaption: undefined,
139	        mentions: undefined,
140	        inReplyTo: undefined,
141	      };
142	      const imageHandle = timeline.sendImage(
143	        fileSource,
144	        new UploadSource.File({ filename: filePath }),
145	        {
146	          height: imageContent.info?.height || BigInt(0),
147	          width: imageContent.info?.width || BigInt(0),
148	          mimetype: imageContent.info?.mimetype || "image/jpeg",
149	          size: imageContent.info?.size || BigInt(0),
150	          thumbnailInfo: imageContent.info?.thumbnailInfo,
151	          thumbnailSource: undefined,
152	          blurhash: imageContent.info?.blurhash || "",
153	          isAnimated: false,
154	        },
155	      );
156	      await imageHandle.join();
157	      return;
158	    }
159	
160	    if (messageType === "video") {
161	      const videoContent = this.getVideoContent(event);
162	      if (!videoContent) throw new Error("Video content not found");
163	
164	      const mediaFile = await client.getMediaFile(
165	        videoContent.source,
166	        videoContent.filename,
167	        videoContent.info?.mimetype || "video/mp4",
168	        true,
169	        undefined,
170	      );
171	      const filePath = mediaFile.path();
172	      const fileSource: UploadParameters = {
173	        source: new UploadSource.File({ filename: filePath }),
174	        caption: videoContent.caption || undefined,
175	        formattedCaption: undefined,
176	        mentions: undefined,
177	        inReplyTo: undefined,
178	      };
179	      const videoHandle = timeline.sendVideo(
180	        fileSource,
181	        new UploadSource.File({ filename: filePath }),
182	        {
183	          height: videoContent.info?.height || BigInt(0),
184	          width: videoContent.info?.width || BigInt(0),
185	          mimetype: videoContent.info?.mimetype || "video/mp4",
186	          size: videoContent.info?.size || BigInt(0),
187	          duration: videoContent.info?.duration || 0,
188	          thumbnailInfo: videoContent.info?.thumbnailInfo,
189	          thumbnailSource: undefined,
190	          blurhash: videoContent.info?.blurhash || "",
191	        },
192	      );
193	      await videoHandle.join();
194	      return;
195	    }
196	
197	    if (messageType === "audio") {
198	      const audioContent = this.getAudioContent(event);
199	      if (!audioContent) throw new Error("Audio content not found");
200	
201	      const mediaFile = await client.getMediaFile(
202	        audioContent.source,
203	        audioContent.filename,
204	        audioContent.info?.mimetype || "audio/mpeg",
205	        true,
206	        undefined,
207	      );
208	      const filePath = mediaFile.path();
209	      const fileSource: UploadParameters = {
210	        source: new UploadSource.File({ filename: filePath }),
211	        caption: undefined,
212	        formattedCaption: undefined,
213	        mentions: undefined,
214	        inReplyTo: undefined,
215	      };
216	      const audioHandle = timeline.sendAudio(fileSource, {
217	        mimetype: audioContent.info?.mimetype || "audio/mpeg",
218	        size: audioContent.info?.size || BigInt(0),
219	        duration: audioContent.info?.duration || 0,
220	      });
221	      await audioHandle.join();
222	      return;
223	    }
224	
225	    if (messageType === "file") {
226	      const fileContent = this.getFileContent(event);
227	      if (!fileContent) throw new Error("File content not found");
228	
229	      const mediaFile = await client.getMediaFile(
230	        fileContent.source,
231	        fileContent.filename,
232	        fileContent.info?.mimetype || "application/octet-stream",
233	        true,
234	        undefined,
235	      );
236	      const filePath = mediaFile.path();
237	      const fileHandle = timeline.sendFile(
238	        {
239	          source: new UploadSource.File({ filename: filePath }),
240	          caption: undefined,
241	          formattedCaption: undefined,
242	          mentions: undefined,
243	          inReplyTo: undefined,
244	        },
245	        {
246	          size: fileContent.info?.size || BigInt(0),
247	          mimetype: fileContent.info?.mimetype || "application/octet-stream",
248	          thumbnailInfo: undefined,
249	          thumbnailSource: undefined,
250	        },
251	      );
252	      await fileHandle.join();
253	      return;
254	    }
255	
256	    throw new Error(`Unsupported message type: ${messageType}`);
257	  };
