286	  public static sendMedia = async (
287	    roomId: string,
288	    asset: Asset,
289	    caption?: string,
290	  ) => {
291	    if (!asset?.uri) throw new Error("No uri found");
292	    const room = MatrixCore.getRoom(roomId);
293	    const timeline = await room.timeline();
294	    if (!timeline) throw new Error("Timeline not found");
295	
296	    const type = asset.type ?? "image/jpeg";
297	    const assetWidth = asset.width ?? 0;
298	    const assetHeight = asset.height ?? 0;
299	    const isVideo = type.startsWith("video/");
300	
301	    const fileSource: UploadParameters = {
302	      source: new UploadSource.File({
303	        filename: decodeURIComponent(asset.uri.replace("file://", "")),
304	      }),
305	      caption: caption || undefined,
306	      formattedCaption: undefined,
307	      mentions: undefined,
308	      inReplyTo: undefined,
309	    };
310	
311	    if (isVideo) {
312	      let thumbnailSource: UploadSource | undefined;
313	      let thumbnailWidth = assetWidth;
314	      let thumbnailHeight = assetHeight;
315	      let thumbnailSize = 0;
316	      let blurhash = "";
317	
318	      try {
319	        const thumbnail = await createThumbnail({
320	          url: asset.uri,
321	          timeStamp: 1000,
322	          format: "jpeg",
323	          maxWidth: 800,
324	          maxHeight: 600,
325	        });
326	
327	        const stat = await RNFS.stat(thumbnail.path);
328	        thumbnailWidth = thumbnail.width;
329	        thumbnailHeight = thumbnail.height;
330	        thumbnailSize = Number(stat.size);
331	        thumbnailSource = new UploadSource.File({ filename: thumbnail.path });
332	
333	        blurhash = await Blurhash.encode(`file://${thumbnail.path}`, 3, 3);
334	      } catch {
335	        // Thumbnail generation is best-effort — send without it if it fails
336	      }
337	
338	      // createThumbnail uses AVAssetImageGenerator with appliesPreferredTrackTransform=true,
339	      // so thumbnail dimensions are rotation-corrected. Derive video display dimensions
340	      // from thumbnail orientation: whichever raw dimension (1920 or 1080) belongs to
341	      // width vs height is determined by whether the thumbnail is landscape or portrait.
342	      const thumbIsLandscape = thumbnailWidth >= thumbnailHeight;
343	      const videoWidth = thumbIsLandscape
344	        ? Math.max(assetWidth, assetHeight)
345	        : Math.min(assetWidth, assetHeight);
346	      const videoHeight = thumbIsLandscape
347	        ? Math.min(assetWidth, assetHeight)
348	        : Math.max(assetWidth, assetHeight);
349	
350	      const videoHandle = timeline.sendVideo(fileSource, thumbnailSource, {
351	        height: BigInt(videoHeight),
352	        width: BigInt(videoWidth),
353	        mimetype: type,
354	        size: BigInt(asset.fileSize ?? 0),
355	        duration: asset.duration ? Math.round(asset.duration * 1000) : 0,
356	        thumbnailInfo: thumbnailSource
357	          ? {
358	              height: BigInt(thumbnailHeight),
359	              width: BigInt(thumbnailWidth),
360	              mimetype: "image/jpeg",
361	              size: BigInt(thumbnailSize),
362	            }
363	          : undefined,
364	        thumbnailSource: undefined,
365	        blurhash,
366	      });
367	      await videoHandle.join();
368	    } else {
369	      const imageHandle = timeline.sendImage(
370	        fileSource,
371	        new UploadSource.File({
372	          filename: decodeURIComponent(asset.uri.replace("file://", "")),
373	        }),
374	        {
375	          height: BigInt(assetHeight),
376	          width: BigInt(assetWidth),
377	          mimetype: type,
378	          size: BigInt(asset.fileSize ?? 0),
379	          thumbnailInfo: {
380	            height: BigInt(assetHeight),
381	            width: BigInt(assetWidth),
382	            mimetype: type,
383	            size: BigInt(asset.fileSize ?? 0),
384	          },
385	          thumbnailSource: undefined,
386	          blurhash: "",
387	          isAnimated: false,
388	        },
389	      );
390	      await imageHandle.join();
391	    }
392	  };
