465	  private static getReceiptTimestamp = (receipt: unknown): number | null => {
466	    if (typeof receipt === "number") return receipt;
467	    if (typeof receipt === "bigint") return Number(receipt);
468	    if (!receipt || typeof receipt !== "object") return null;
469	
470	    const maybeReceipt = receipt as Record<string, unknown>;
471	    const candidate =
472	      maybeReceipt.ts ??
473	      maybeReceipt.timestamp ??
474	      maybeReceipt.originServerTs ??
475	      maybeReceipt.origin_server_ts;
476	
477	    if (typeof candidate === "number") return candidate;
478	    if (typeof candidate === "bigint") return Number(candidate);
479	    if (typeof candidate === "string") {
480	      const parsed = Number(candidate);
481	      return Number.isFinite(parsed) ? parsed : null;
482	    }
483	
484	    return null;
485	  };
