import {
  type EventTimelineItem,
  MessageType_Tags,
  MsgLikeKind_Tags,
  type TimelineItemContent,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";

export const getMessageTextContent = (content: TimelineItemContent): string => {
  if (content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;

      if (msgType?.tag === MessageType_Tags.Text) {
        return kind.inner.content.body;
      }

      if (msgType?.tag === MessageType_Tags.Image) {
        return msgType.inner.content.filename;
      }

      if (msgType?.tag === MessageType_Tags.Video) {
        return msgType.inner.content.filename;
      }

      if (msgType?.tag === MessageType_Tags.Audio) {
        return msgType.inner.content.filename;
      }

      return kind.inner.content.body;
    }
  }

  return "";
};

export const getEventTextContent = (event: EventTimelineItem): string =>
  getMessageTextContent(event.content);

